import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.DMVuHR7L.js";const p=JSON.parse('{"title":"Release plan: alpha → beta → GA","description":"","frontmatter":{},"headers":[],"relativePath":"devs/release-plan.md","filePath":"devs/release-plan.md","lastUpdated":1778762946000}'),r={name:"devs/release-plan.md"};function s(l,e,n,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="release-plan-alpha-→-beta-→-ga" tabindex="-1">Release plan: alpha → beta → GA <a class="header-anchor" href="#release-plan-alpha-→-beta-→-ga" aria-label="Permalink to &quot;Release plan: alpha → beta → GA&quot;">​</a></h1><p>This is the operational plan for moving WebLogcat from &quot;alpha&quot; (small private testing group) to &quot;beta&quot; (broader public sharing — Reddit, HN-style channels) to general availability (drop the beta pill, ship v1.0). It&#39;s written so a human can follow it directly <em>and</em> so an agent can be pointed at a single phase and execute it.</p><p>The repo currently sits in <strong>alpha</strong>. The pre-release cleanup pass is done.</p><hr><h2 id="quick-reference-for-an-agent" tabindex="-1">Quick reference for an agent <a class="header-anchor" href="#quick-reference-for-an-agent" aria-label="Permalink to &quot;Quick reference for an agent&quot;">​</a></h2><p>If a human asks you to &quot;do the alpha release prep&quot;, or &quot;promote to beta&quot;, or anything else release-shaped, this document is the authoritative checklist. Each phase has:</p><ul><li>A <strong>goal</strong> (what state the repo ends in).</li><li>A <strong>prerequisites</strong> block (anything that must already be true).</li><li>A <strong>steps</strong> list, marked <code>[code]</code> (you can do it directly via PR/commit), <code>[infra]</code> (GitHub UI / settings — needs the human), or <code>[external]</code> (announcements / outreach — needs the human).</li></ul><p>Always:</p><ul><li>Land each phase as a single small PR where possible.</li><li>Don&#39;t bump the version manually if it&#39;s just a bug-fix; the <code>version-bump.yml</code> workflow handles patch versions automatically on every push to <code>main</code>. <strong>Major / minor bumps are explicit edits to <code>package.json</code></strong> and only happen at the phase boundaries below.</li><li>Don&#39;t open a PR labeled &quot;alpha → beta promotion&quot; unless every box in the <strong>Beta prerequisites</strong> is ticked.</li></ul><p>If a step says <code>[infra]</code> or <code>[external]</code> and the human hasn&#39;t done it, <em>don&#39;t</em> try to do it for them via a roundabout path (e.g. don&#39;t push a workflow that scrapes Reddit). Surface that the step needs their action and pause.</p><hr><h2 id="phase-0-—-pre-release-cleanup-done" tabindex="-1">Phase 0 — Pre-release cleanup (done) <a class="header-anchor" href="#phase-0-—-pre-release-cleanup-done" aria-label="Permalink to &quot;Phase 0 — Pre-release cleanup (done)&quot;">​</a></h2><p>This is recorded for completeness; the actions are already on <code>main</code>.</p><ul><li>[x] Repo audited for committed secrets / personal info (none found).</li><li>[x] <code>LICENSE</code> file exists at the root (MIT, matching <code>package.json</code>).</li><li>[x] Internal-only dev docs removed: <ul><li><code>docs/TASKS.md</code> (superseded by GitHub Issues).</li><li><code>docs/LEARNINGS.md</code> (operational notes from initial development).</li><li><code>design/</code> (handoff prototypes — historical reference, no longer needed).</li></ul></li><li>[x] Public docs reorganised into a published site: <ul><li><code>README.md</code> is user-first (live URL, supported browsers, one-line pitch, screenshot, pointer to the docs site).</li><li><code>docs/</code> is a VitePress app published at <code>&lt;base&gt;/docs/</code> with three audience-segmented sections: <code>features/</code> for end users, <code>devs/</code> for contributors (this page included), and <code>bots/</code> for AI agents.</li><li><code>CLAUDE.md</code> at the root is the agent entry-point and points into <code>docs/bots/</code> for the operational contracts.</li></ul></li><li>[x] CI surface in place: <ul><li><code>ci.yml</code> (typecheck / lint / unit / build / e2e on every PR).</li><li><code>version-bump.yml</code> (auto-increments patch on <code>main</code> pushes via PR + auto-merge).</li><li><code>deploy.yml</code> (publishes <code>main</code> → staging, <code>release</code> → prod).</li><li><code>promote.yml</code> (manual <code>workflow_dispatch</code> button to fast-forward <code>release</code> to <code>main</code>).</li></ul></li><li>[x] Issue templates: <code>bug_report.md</code>, <code>feature_request.md</code> under <code>.github/ISSUE_TEMPLATE/</code>. Drop them into the repo if missing — they collect structured reports during alpha/beta.</li></ul><hr><h2 id="phase-1-—-alpha-current" tabindex="-1">Phase 1 — Alpha (current) <a class="header-anchor" href="#phase-1-—-alpha-current" aria-label="Permalink to &quot;Phase 1 — Alpha (current)&quot;">​</a></h2><p><strong>Goal:</strong> small private cohort uses the staging URL and reports back.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>[x] Phase 0 boxes all ticked.</li><li>[x] The transferred repo&#39;s GitHub side is fully wired up: <code>BOT_PAT</code> recreated, Pages re-enabled, &quot;Allow auto-merge&quot; ticked, ruleset bypass actor verified, <code>release</code> ruleset created (block force pushes + restrict deletions).</li><li>[x] At least one end-to-end test pass on a real Android device by the maintainer.</li></ul><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li><code>[infra]</code> Create or pin a GitHub Discussion / pinned Issue titled &quot;Alpha feedback&quot; containing: <ul><li>the staging URL,</li><li>supported browsers (Chromium-only, WebUSB),</li><li>a &quot;what to try&quot; list (each widget, drag-to-repivot, pairing on a real device, log streaming, etc.),</li><li>a pointer to the bug-report template for issues.</li></ul></li><li><code>[external]</code> Hand-pick the alpha cohort (5–15 people who&#39;ll actually plug in a real device and report). Send them the URL + the &quot;what to try&quot; list directly.</li><li><code>[code]</code> Iterate on feedback as PRs against <code>main</code>. Patch bumps land automatically. Promote to <code>release</code> (and therefore to production) via the <strong>Actions → Promote main to release</strong> workflow when the maintainer is satisfied with a checkpoint.</li></ol><p>Don&#39;t:</p><ul><li>Add analytics / telemetry in alpha. Direct feedback at this scale is enough and avoids consent friction.</li><li>Open this up to broader audiences (Reddit etc.) until the <strong>Beta prerequisites</strong> are all ticked.</li></ul><h3 id="exit-criteria-when-to-consider-promoting-to-beta" tabindex="-1">Exit criteria (when to consider promoting to beta) <a class="header-anchor" href="#exit-criteria-when-to-consider-promoting-to-beta" aria-label="Permalink to &quot;Exit criteria (when to consider promoting to beta)&quot;">​</a></h3><ul><li>[ ] No P0 bugs reported in the last 2 weeks.</li><li>[ ] All five widgets exercised on at least one real Pixel / Galaxy / similar Android 13+ device by someone other than the maintainer.</li><li>[ ] No outstanding issues marked <code>release-blocker</code>.</li></ul><hr><h2 id="phase-2-—-beta-broader-sharing" tabindex="-1">Phase 2 — Beta (broader sharing) <a class="header-anchor" href="#phase-2-—-beta-broader-sharing" aria-label="Permalink to &quot;Phase 2 — Beta (broader sharing)&quot;">​</a></h2><p><strong>Goal:</strong> the app is shared on Reddit / HN-style channels and absorbs public feedback.</p><h3 id="prerequisites-1" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites-1" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>[ ] All Phase 1 exit criteria ticked.</li><li>[ ] A short launch post draft exists (paragraph + one screenshot + link).</li></ul><h3 id="steps-agent-runnable" tabindex="-1">Steps (agent-runnable) <a class="header-anchor" href="#steps-agent-runnable" aria-label="Permalink to &quot;Steps (agent-runnable)&quot;">​</a></h3><ol><li><code>[code]</code> Replace the alpha branding with beta: <ul><li>In <code>src/components/Dashboard.tsx</code>, change the <code>dash-brand-beta</code> pill text from <code>alpha</code> to <code>beta</code> (and the <code>aria-label</code> from <code>Alpha release</code> to <code>Beta release</code>). The CSS class stays <code>dash-brand-beta</code> — don&#39;t churn the styling.</li><li>In <code>src/components/EmptyState.tsx</code>, change the <code>empty-alpha</code> pill the same way.</li><li>One PR, simple commit.</li></ul></li><li><code>[code]</code> Bump the version to a meaningful minor in <code>package.json</code> — e.g. <code>0.5.0</code>. The auto-patch-bump will continue from there. Land in the same PR as the branding change so the <code>package.json</code> version and the visible pill agree from one commit forward.</li><li><code>[infra]</code> Optionally enable GitHub Discussions on the repo for free-form Q&amp;A (Settings → General → Features → Discussions).</li><li><code>[external]</code> Pin a &quot;Beta feedback&quot; issue / discussion replacing the alpha one — same structure, broader audience.</li><li><code>[external]</code> Post the launch announcement. Primary: r/androiddev. Optional secondaries: r/webdev, Hacker News&#39; Show.</li><li><code>[code]</code> (optional) Wire in privacy-respecting analytics if you want a sense of scale — Plausible, Umami, or a tiny Cloudflare Worker counter. Add a one-line note to the README disclosing it. Skip if you&#39;d rather not.</li></ol><p>Don&#39;t:</p><ul><li>Bump straight to <code>1.0.0</code> from beta. Keep major reserved for the GA boundary so users have a clear &quot;stable&quot; signal to look for.</li><li>Remove the beta pill until <strong>Phase 3</strong> runs.</li></ul><h3 id="exit-criteria" tabindex="-1">Exit criteria <a class="header-anchor" href="#exit-criteria" aria-label="Permalink to &quot;Exit criteria&quot;">​</a></h3><ul><li>[ ] 30 days with no P0/P1 bugs.</li><li>[ ] At least 3–5 people other than the maintainer have used the app on real hardware and reported back.</li><li>[ ] All five widgets exercised in the wild (cumulative).</li><li>[ ] No outstanding issues marked <code>release-blocker</code>.</li></ul><hr><h2 id="phase-3-—-ga-1-0" tabindex="-1">Phase 3 — GA (1.0) <a class="header-anchor" href="#phase-3-—-ga-1-0" aria-label="Permalink to &quot;Phase 3 — GA (1.0)&quot;">​</a></h2><p><strong>Goal:</strong> beta pill removed, version is <code>1.0.0</code>, the app is &quot;stable&quot; in the README sense.</p><h3 id="prerequisites-2" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites-2" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>[ ] All Phase 2 exit criteria ticked.</li></ul><h3 id="steps-agent-runnable-1" tabindex="-1">Steps (agent-runnable) <a class="header-anchor" href="#steps-agent-runnable-1" aria-label="Permalink to &quot;Steps (agent-runnable)&quot;">​</a></h3><ol><li><code>[code]</code> Remove the release pill from both surfaces: <ul><li>In <code>src/components/Dashboard.tsx</code>, delete the <code>&lt;span className=&quot;dash-brand-beta&quot;&gt;…&lt;/span&gt;</code> element.</li><li>In <code>src/components/EmptyState.tsx</code>, delete the <code>&lt;span className=&quot;empty-alpha&quot;&gt;…&lt;/span&gt;</code> element.</li><li>Drop the <code>.dash-brand-beta</code> and <code>.empty-alpha</code> CSS rules (they have no other consumers).</li></ul></li><li><code>[code]</code> Bump the version to <code>1.0.0</code> in <code>package.json</code>. The auto-bump moves on as <code>1.0.1</code>, <code>1.0.2</code> from there.</li><li><code>[code]</code> Update <code>README.md</code>: <ul><li>Drop any &quot;alpha&quot;/&quot;beta&quot;/&quot;experimental&quot; disclaimers.</li><li>Add a stable-version badge if desired (shields.io <code>version-1.0.0-blue</code>, or just remove the pre-release tone).</li></ul></li><li><code>[code]</code> Create <code>CHANGELOG.md</code> (or use GitHub Releases — same thing). Cut a <code>v1.0.0</code> release with a curated highlights list of the alpha + beta work. Link to it from the README.</li><li><code>[external]</code> Tag the GitHub Release; consider a follow-up post on the same channels you used at beta launch.</li></ol><p>Don&#39;t:</p><ul><li>Drop backward compatibility for the <code>?d=</code> URL state format — shared URLs are now public surface. Keep <code>decode()</code>&#39;s legacy shape acceptance.</li></ul><h3 id="exit-criteria-1" tabindex="-1">Exit criteria <a class="header-anchor" href="#exit-criteria-1" aria-label="Permalink to &quot;Exit criteria&quot;">​</a></h3><ul><li>[ ] <code>package.json</code> version starts with <code>1.</code>.</li><li>[ ] No <code>alpha</code>/<code>beta</code> text in the rendered UI.</li><li>[ ] <code>v1.0.0</code> GitHub Release exists.</li></ul><hr><h2 id="things-to-keep-in-mind-across-all-phases" tabindex="-1">Things to keep in mind across all phases <a class="header-anchor" href="#things-to-keep-in-mind-across-all-phases" aria-label="Permalink to &quot;Things to keep in mind across all phases&quot;">​</a></h2><ul><li><strong>Don&#39;t change the repo URL again</strong> between alpha and 1.0. Every reshare you do compounds the redirect debt; pick the final owner before alpha if at all possible.</li><li><strong>Auto-bump policy:</strong> keep the patch bump on every <code>main</code> commit. Major / minor are manual at the phase boundaries above.</li><li><strong>Backwards-compatible URL state:</strong> the <code>?d=</code> payload is now a public surface. <code>decode()</code> already accepts the legacy <code>{ layout, tileSettings }</code> shape — keep that compatibility through 1.0 and ideally beyond.</li><li><strong>History is read-only:</strong> never rewrite past commit history to clean up co-author / session-URL footers. They&#39;re noise but rewriting invalidates every existing PR/issue link to a SHA, and that&#39;s a worse trade-off.</li></ul>',50)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
